/** Fallback for characters not in the table (emoji are stripped upstream). */
export const GLYPH_ADVANCE_FALLBACK = 0.54;

/** Width of `text` at `fontSize`, in export-space pixels. */
export function measureTextWidth(
  text: string,
  fontSize: number,
  fontWeight: number,
): number {
  const table = fontWeight >= 800 ? GLYPH_ADVANCE_800 : GLYPH_ADVANCE_700;
  let total = 0;
  for (const ch of text) total += table[ch] ?? GLYPH_ADVANCE_FALLBACK;
  return total * fontSize;
}
